select quarter(launch_date) as launch_quarter, case when category in ('Grocery', 'Fashion') then 'group_a' else 'other' end as category_group, sum(case when category = 'Home' then 1 else 0 end) as home_count, min(stock_qty) as min_stock_qty from products where month(launch_date) in (4, 6, 8) or cost >= 660 group by quarter(launch_date), case when category in ('Grocery', 'Fashion') then 'group_a' else 'other' end order by launch_quarter desc, category_group limit 10
